import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String data = scanner.nextLine();
        int totalLength = data.length();

        System.out.print(data.charAt(0));

        boolean atFlag = false;
        int currentIndex = 1;

        while (currentIndex < totalLength) {
            if (data.charAt(currentIndex) == 'a' && !atFlag && isAtSequence(data, currentIndex, totalLength)) {
                System.out.print('@');
                atFlag = true;
                currentIndex += 2;
                continue;
            }

            if (data.charAt(currentIndex) == 'd' && isDotSequence(data, currentIndex, totalLength)) {
                System.out.print('.');
                currentIndex += 3;
                continue;
            }

            System.out.print(data.charAt(currentIndex));
            currentIndex++;
        }
        scanner.close();
    }

    private static boolean isDotSequence(String data, int currentIndex, int totalLength) {
        return (currentIndex + 2) < (totalLength) && data.charAt(currentIndex + 1) == 'o' && data.charAt(currentIndex + 2) == 't';
    }

    private static boolean isAtSequence(String data, int currentIndex, int totalLength) {
        return (currentIndex + 1) < totalLength && data.charAt(currentIndex + 1) == 't';
    }
}
